import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.CD3qHYUq.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1793136727000}`),a={name:`guide/introduction.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>BullMQ is based in 4 classes that together can be used to resolve many different problems. These classes are <a href="https://docs.bullmq.io/api/classes/v6.Queue.html" target="_blank" rel="noreferrer"><em><strong>Queue</strong></em></a>, <a href="https://docs.bullmq.io/api/classes/v6.Worker.html" target="_blank" rel="noreferrer"><em><strong>Worker</strong></em></a>, <a href="https://docs.bullmq.io/api/classes/v6.QueueEvents.html" target="_blank" rel="noreferrer"><em><strong>QueueEvents</strong></em></a> and <a href="https://docs.bullmq.io/api/classes/v6.FlowProducer.html" target="_blank" rel="noreferrer"><em><strong>FlowProducer</strong></em></a>.</p><p>The first class you should know about is the <em>Queue</em> class. This class represents a queue and can be used for adding <em><strong>jobs</strong></em> to the queue as well as some other basic manipulation such as pausing, cleaning or getting data from the queue. It is also used to create <a href="./job-schedulers/README"><em><strong>job schedulers</strong></em></a>, which produce repeatable jobs according to a cron expression or a fixed interval.</p><p>Jobs in BullMQ are basically a user created data structure that can be stored in the queue. Jobs are processed by <em><strong>workers</strong></em>. A <em>Worker</em> is the second class you should be aware about. Workers are instances capable of processing jobs. You can have many workers, either running in the same process, or in separate processes as well as in different machines. They will all consume jobs from the queue and mark the jobs as completed or failed.</p><p>The <em>QueueEvents</em> class lets you listen, from any process, to the <a href="./events/README">events</a> produced by all the workers of a given queue, such as jobs being completed, failing or reporting progress.</p><p>Finally, the <em>FlowProducer</em> class allows you to add <a href="./flows/README">flows</a>: trees of jobs with parent-child dependencies, where a parent job is only processed once all its children have completed, even if the children live in different queues.</p><p>Besides these classes, BullMQ also includes the <a href="./relay/README"><em><strong>Relay</strong></em></a> (experimental), which lets the processes of your system exchange real-time messages through the same datastore used by your queues.</p><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to “Backends”">​</a></h2><p>The classes above are datastore agnostic. They delegate every operation to a <em>backend</em>, which is responsible for storing the jobs and performing all the state transitions atomically. BullMQ ships with two backends:</p><ul><li><strong>Redis™</strong> (default): works with Redis 6.2 or newer and compatible servers such as Valkey and Dragonfly, using any of the supported clients (ioredis, node-redis, Bun&#39;s Redis client or Valkey GLIDE). See <a href="./connections">Connections</a>.</li><li><strong>PostgreSQL</strong>: runs the same API on PostgreSQL 13 or newer. See <a href="./postgresql">PostgreSQL backend</a>.</li></ul><p>Unless stated otherwise, the rest of this guide applies to both backends. Any difference is documented in the <a href="./postgresql#feature-parity-and-limitations">feature parity</a> section of the PostgreSQL backend.</p><h2 id="other-languages" tabindex="-1">Other languages <a class="header-anchor" href="#other-languages" aria-label="Permalink to “Other languages”">​</a></h2><p>This guide uses the TypeScript package, which runs on Node.js and Bun. BullMQ is also available for <a href="./../python/introduction">Python</a>, <a href="./../elixir/introduction">Elixir</a>, <a href="./../dotnet/introduction">.NET</a>, <a href="./../rust/introduction">Rust</a> and <a href="./../php/introduction">PHP</a>. All the SDKs share the same data model, so the concepts described in this guide apply to them as well, and producers and workers written in different languages can work together on the same queues.</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};